import{_ as a,C as o,o as l,c as r,E as i,a2 as d}from"./chunks/framework.BOeh4kYD.js";const f=JSON.parse('{"title":"每个智能体都通过检查，为什么系统仍可能不安全？","description":"","frontmatter":{"title":"每个智能体都通过检查，为什么系统仍可能不安全？","date":"2026-09-07","column":"digital-employee","category":"daily","article_type":"technical-analysis","edition":"research-center","research_question":"当每个数字员工都通过自己的局部安全检查时，还需要什么证据才能说明不可信影响无法沿消息、共享状态、委派权限或恢复路径抵达受保护效果？","summary":"一项覆盖197篇多智能体安全工作的系统化研究提醒我们：局部通过不等于端到端安全。真正需要闭合的是从影响来源到最终效果的完整权限路径，包括可观察范围、干预能力、信任假设、替代路径和传播后的恢复。","sources":["research/analysis/Q-20260907-01-authority-to-effect-path-closure.md"],"item_id":"Q-20260907-01","lifecycle":"Published","cover":"/assets/covers/daily-2026-09-07-local-safety-does-not-close-path-editorial-v2.webp","evidence_status":"Completed","citation_status":"Completed","editing_status":"Completed","publication_authorized":true},"headers":[],"relativePath":"zh/digital-employee/2026-09-07-local-safety-does-not-close-path.md","filePath":"zh/digital-employee/2026-09-07-local-safety-does-not-close-path.md","lastUpdated":1788926442000}'),s={name:"zh/digital-employee/2026-09-07-local-safety-does-not-close-path.md"};function p(n,t,h,c,u,m){const e=o("ArticleCover");return l(),r("div",null,[i(e,{image:"/assets/covers/daily-2026-09-07-local-safety-does-not-close-path-editorial-v2.webp",kicker:"数字员工 · 每日研究",title:"每个智能体都通过检查，为什么系统仍可能不安全？",summary:"一项覆盖197篇多智能体安全工作的系统化研究提醒我们：局部通过不等于端到端安全。真正需要闭合的是从影响来源到最终效果的完整权限路径，包括可观察范围、干预能力、信任假设、替代路径和传播后的恢复。",version:"Q-20260907-01",status:"Daily Runtime V5 · 2026-09-07",languageHref:"/en/digital-employee/2026-09-07-local-safety-does-not-close-path",languageLabel:"English"}),t[0]||(t[0]=d('<h1 id="每个智能体都通过检查-为什么系统仍可能不安全" tabindex="-1">每个智能体都通过检查，为什么系统仍可能不安全？ <a class="header-anchor" href="#每个智能体都通过检查-为什么系统仍可能不安全" aria-label="Permalink to &quot;每个智能体都通过检查，为什么系统仍可能不安全？&quot;">​</a></h1><p>设想一个多智能体系统：发送者通过输入检查，中间智能体只读取自己获准的数据，工具调用也通过权限门禁，最后执行者同样没有越权。逐个看，每一步都“合法”。但如果一条低权限来源的信息先进入共享记忆，再被摘要为一条没有来源标签的结论，随后由高权限智能体据此调用工具，那么局部检查全部通过，最终效果仍可能违背最初的授权目的。</p><p>这正是多智能体安全最容易出现的错觉：<strong>把每个 Worker（执行智能体）都安全，等同于整个系统安全。</strong> 同日研究对象引用的一项系统化研究覆盖 197 篇多智能体安全工作，并另外审计 44 篇评估类工作。它提供的最重要启发不是某一种具体防御，而是重新定义安全对象：真正需要证明的不是某个节点“没有犯错”，而是从不可信影响的来源到受保护效果的完整路径是否闭合。</p><h2 id="局部通过-为什么仍会形成全局失败" tabindex="-1">局部通过，为什么仍会形成全局失败 <a class="header-anchor" href="#局部通过-为什么仍会形成全局失败" aria-label="Permalink to &quot;局部通过，为什么仍会形成全局失败&quot;">​</a></h2><p>单个智能体通常只能证明局部命题：这条消息格式合法、这个调用在权限表内、这个模型输出没有命中规则、这个工具目标属于允许范围。问题在于，多智能体系统的效果是沿关系传播的。</p><p>一次影响可能经历：原始消息 → 共享状态 → 摘要或压缩 → 中间角色判断 → 权限委派 → 工具执行。只要其中某一步丢失来源、改变语义边界，或把低权限信息包装成高权限主体的判断，最终动作就可能获得一条形式上合法、实质上错误的权限路径。</p><p>因此，局部安全测试回答的是“这一跳是否符合本地规则”，而系统安全还需要回答“从哪里来的影响，经过哪些转换，最终为什么获得了这个效果”。两者不是同一个证明对象。</p><h2 id="_197-篇工作共同暴露出的五个证据缺口" tabindex="-1">197 篇工作共同暴露出的五个证据缺口 <a class="header-anchor" href="#_197-篇工作共同暴露出的五个证据缺口" aria-label="Permalink to &quot;197 篇工作共同暴露出的五个证据缺口&quot;">​</a></h2><p>主研究把多智能体安全组织为跨主体的执行路径，并用六类交互接口、八类高频攻击路径描述风险。对防御机制的评价又显式区分路径目标、观察、干预、信任边界和恢复。</p><p>这些字段最有价值的地方，在于它们阻止一个局部 PASS（通过）悄悄替代整个系统证明：</p><table tabindex="0"><thead><tr><th>证据问题</th><th>它真正回答什么</th><th>局部 PASS 不能替代什么</th></tr></thead><tbody><tr><td>路径目标</td><td>控制准备切断哪种系统级风险和哪段传播路线</td><td>不能说明其他路线不存在</td></tr><tr><td>观察范围</td><td>控制能看到哪些消息、主体、状态或轨迹</td><td>看不到的路径仍可能存在</td></tr><tr><td>干预能力</td><td>可以阻断、改写、隔离、撤销或修复什么</td><td>仅看见不等于能阻止</td></tr><tr><td>信任边界</td><td>哪些身份、日志、拓扑、成员关系必须可信</td><td>默认信任不能被隐藏</td></tr><tr><td>恢复证据</td><td>传播后的派生状态和权限如何被定位、修复并复核</td><td>遏制源头不等于系统恢复</td></tr></tbody></table><p>这也是为什么“我们已经把恶意发送者封禁”常常只是事故中段。影响一旦进入持久状态，系统里还可能留着由它派生的记忆、文件、凭据、委派权限、已创建的子主体，甚至已经写入外部系统的效果。</p><h2 id="安全对象应该是一条-来源到效果-的可追踪链" tabindex="-1">安全对象应该是一条“来源到效果”的可追踪链 <a class="header-anchor" href="#安全对象应该是一条-来源到效果-的可追踪链" aria-label="Permalink to &quot;安全对象应该是一条“来源到效果”的可追踪链&quot;">​</a></h2><p>一个受治理的运行系统可以把安全证据绑定到一条最小的来源到效果链：</p><p><code>影响来源 → 被接纳的消息或制品 → 状态与主体转换 → 委派权限 → 受保护效果</code></p><p>关键不在于把所有内部推理都记录下来，而是保留足以回答责任和授权的问题：原始影响来自谁；哪些转换保留或改变了它的语义；哪一个中间主体把它带入新的权限域；最终效果依赖了哪项委派权；当前控制实际能看到并阻断哪些路线。</p><p>于是，权限门禁不再只问“某个智能体能不能调用某个工具”，还要问“这次调用所依据的权力，是如何变得可达的”。如果高权限调用由低权限来源经共享状态间接塑造，那么调用本身合规，并不自动意味着其来源链合规。</p><p>这不是要求所有系统都采用一个中央总监控器。恰恰相反，中心化观察会制造新的敏感数据集中和控制平面风险。治理要求是明确写出观察覆盖与盲区，而不是默认“看得更多就一定更安全”。</p><h2 id="替代路径才是最难的部分" tabindex="-1">替代路径才是最难的部分 <a class="header-anchor" href="#替代路径才是最难的部分" aria-label="Permalink to &quot;替代路径才是最难的部分&quot;">​</a></h2><p>封掉一条已知路线，并不能说明目标不可达。只要相同影响可以经另一组主体、另一份共享状态、另一个工具权限或一次恢复重放重新抵达受保护效果，路径就没有真正闭合。</p><p>因此，系统级安全检查需要一种“替代路线意识”：当成员、拓扑、工具权限或路由规则变化时，原来的安全判断是否仍成立？某条关系被移除后，任务本身是否仍有可比较的安全命题？哪些路径是被观察到的，哪些只是推测不存在？</p><p>同日分析建议把反事实测试作为一种有界工具：在不破坏任务含义的前提下，移除某条关系或能力，观察受保护效果是否仍可达。它不能自动证明因果，但可以暴露“我们以为只有这一条路”的错误假设。</p><h2 id="遏制不是恢复" tabindex="-1">遏制不是恢复 <a class="header-anchor" href="#遏制不是恢复" aria-label="Permalink to &quot;遏制不是恢复&quot;">​</a></h2><p>多智能体安全里一个非常重要、又常被压缩成一个状态的区别是：Containment（遏制）与 Recovery（恢复）不是同一件事。</p><p>遏制回答“影响还能不能继续扩散”；恢复回答“已经被影响的状态、制品、凭据、权限和主体是否已经被找到、撤销、修复，并重新验证为可信”。如果只是停止原发送者，却继续使用它污染过的摘要、缓存或权限，那么系统实际上仍在消费旧影响。</p><p>因此，一个成熟的事故状态机至少要允许出现：“源头已隔离，但派生状态尚未恢复”。这种显式不确定，比把系统直接标成“安全”更有价值。</p><h2 id="反方问题-是不是记录越多越安全" tabindex="-1">反方问题：是不是记录越多越安全？ <a class="header-anchor" href="#反方问题-是不是记录越多越安全" aria-label="Permalink to &quot;反方问题：是不是记录越多越安全？&quot;">​</a></h2><p>不是。完整追踪本身也有成本：隐私暴露、存储压力、控制面集中风险，以及日志本身被伪造或污染的可能性。路径证据应以最小充分为目标，而不是无限采集。</p><p>同样，一个全局观察者未必比局部观察者更可靠。全局视图可能覆盖更广，却依赖更粗粒度的数据和更强的信任假设；局部控制上下文更精确，却可能看不到替代路径。真正需要持久化的是“这个控制看到什么、没看到什么、能干预什么、依赖谁可信”。</p><h2 id="对数字员工系统最直接的工程含义" tabindex="-1">对数字员工系统最直接的工程含义 <a class="header-anchor" href="#对数字员工系统最直接的工程含义" aria-label="Permalink to &quot;对数字员工系统最直接的工程含义&quot;">​</a></h2><p>如果数字员工要长期运行，而不是一次性回答问题，下面几项事实不应只存在于模型上下文中：</p><ul><li>消息、摘要、共享状态和交接中的来源与授权上下文；</li><li>高权限效果所依赖的中间主体与委派关系；</li><li>每个系统级控制的观察范围、干预范围与盲区；</li><li>成员、拓扑、工具权限变化后需要重新验证的安全判断；</li><li>遏制之后仍待撤销或修复的派生制品、凭据、权限和主体。</li></ul><p>这组要求不会自动给出一个“万能安全架构”。它只是把证明责任放回正确的位置：<strong>不是问每个智能体是否都通过了自己的检查，而是问整个权限—效果路径是否在当前信任假设下被看见、可中断、无未评估替代路线，并且传播后的状态能够恢复。</strong></p><h2 id="证据边界与开放问题" tabindex="-1">证据边界与开放问题 <a class="header-anchor" href="#证据边界与开放问题" aria-label="Permalink to &quot;证据边界与开放问题&quot;">​</a></h2><p>当前证据来自系统化研究和评估审计，不是某个生产运行时的端到端证明。197 篇工作提供了广泛样本，但不能覆盖所有快速变化的部署实践；五项证据维度是分析框架，也不是已经机械验证的统一标准。</p><p>仍待回答的问题包括：来源信息经过上下文压缩后怎样既保持可验证又不泄露过多内容；动态系统能否在线检查替代路径；哪些效果必须前置阻断，哪些允许事后补偿恢复；以及怎样在不建立一个高风险“全知控制器”的情况下获得足够的路径证据。</p><p><strong>证据与引用：</strong></p><ul><li><a href="https://arxiv.org/html/2609.00595v1" target="_blank" rel="noreferrer">Multi-Agent Systems Security Systematization（多智能体系统安全系统化研究）</a></li></ul>',38))])}const y=a(s,[["render",p]]);export{f as __pageData,y as default};
